}

    /// <summary>
    /// Extracts all the orders by salesid and category based on the filters.
    /// </summary>
    public void insertOrders()
    {
        //Case1: Insert records group by SalesId & Category
        container           cont;
        SalesLine           lineLoc;
        int                 i       = 0;
        RecordInsertList    list    = new RecordInsertList(tableNum(METOrderExtractScreenTmp), false, false, false, false, false, metOrderExtractScreenTmp);
        boolean             extractConfirmedOrder = WHSParameters::find().METExtractConfirmedOrders;

        while select SalesId from salesTableLoc group by salesTableLoc.SalesId
                where  salesTableLoc.SalesStatus == SalesStatus::Backorder
                && ((!extractConfirmedOrder || salesTableLoc.DocumentStatus  != DocumentStatus::None)
                && salesTableLoc.DocumentStatus             != DocumentStatus::Cancelled)
                && salesTableLoc.SalesType                  == SalesType::Sales
                && salesTableLoc.METOrderExtractStatus      == extracted
                && (!route  || salesTableLoc.METRoute       == route)
                && (salesTableLoc.ShippingDateConfirmed     >=  shippingDateFrom 
                && salesTableLoc.ShippingDateConfirmed      <=  shippingDateTo)
                && (!salesTableLoc.InterCompanyOriginalSalesId)
                //CS - CB173_SalesOrderExtract - PS
                && (!custAcc || salesTableLoc.CustAccount   == custAcc)
                && (!salesOrderType || salesTableLoc.METSalesOrderType == salesOrderType)
                && (!site || salesTableLoc.InventSiteId  == site)
                && (!warehouse || salesTableLoc.InventLocationId == warehouse)
            exists join lineLoc
                where lineLoc.SalesId   == salesTableLoc.SalesId
            exists join metInventItemOrderSetup
                where metInventItemOrderSetup.ItemId   == lineLoc.ItemId
                &&      metInventItemOrderSetup.SiteId   == site
        //CE - CB173_SalesOrderExtract - PS
        {
            metOrderExtractScreenTmp.SalesId = salesTableLoc.SalesId;
            list.add(metOrderExtractScreenTmp);
           
            i += 1;
            cont = conins(cont, i, metOrderExtractScreenTmp.SalesId);
        }
        list.insertDatabase();
        select * from metOrderExtractScreenTmp;
        this.parmMETOrderExtractScreenTmp(metOrderExtractScreenTmp);
        this.parmCon(cont);
        
    }

