    /// <summary>
    /// Calculates weigt and other related fields and updates
    /// </summary>
    /// <param name = "_metOrderExtractScreenTmp">Tmp table buffer</param>
    /// <param name = "_con">Container</param>
    [SuppressBPWarning('BPCheckNestedLoopinCode', 'This is required as itterative strategy needs to incorporated for better handling')]
    public void calculateTemp(METOrderExtractScreenTmp  _metOrderExtractScreenTmp, Container _con = conNull())
    {
        //CS - CB173_SalesOrderExtract - PS
        #define.Million(1000000000)
        
        METTotalPallets     totalPal, estTotalPal;
        Weight              weight, actualWeight;
        Volume              volume, actualVolume;
        METCase             casesLoc, actualCases;
        METBrokenCase       brokenCase, actBrokenCases;
        METInventLocation   metInventLocationLoc;
        //SalesTable          stLoc;
        //salesLine           slLoc;

        totalPal    = 0;
        estTotalPal = 0;
        #OCCRetryCount

        try
        {
            this.initParams();

            int                 i;
            //METItemTypes        itemTypes;
            Container           cont    = _con;
            volumeMap                   = new Map (Types::String, Types::Real);
            itemTypeMap                 = new Map (Types::String, Types::String);
            totalPallets                = this.parmTotalpallets();
            
            for (i = 1 ; i <= conLen(cont) ; i++)
            {
                SalesId id      = conpeek(cont, i);
                weight          = 0;
                volume          = 0;
                casesLoc        = 0;
                brokenCase      = 0;
                actBrokenCases  = 0;
                actualCases     = 0;
                actualVolume    = 0;
                actualWeight    = 0;

                SalesLine           salesLineLoc;
                while select salesLineLoc where salesLineLoc.SalesId == id
                {
                    METSalesLine    metsalesLineLoc  = METSalesLine::find(salesLineLoc.RecId);

                    weight          += salesLineLoc.SalesQty * metsalesLineLoc.SalesUnitWeight;
                    volume          += salesLineLoc.SalesQty * metsalesLineLoc.SalesUnitVolume;
                    casesLoc        +=  salesLineLoc.displayMETcases();
                    brokenCase      +=  salesLineLoc.displayMETBrokenCase();
                    actBrokenCases  += salesLineLoc.displayMETActualBrokenCase();
                    actualCases     += salesLineLoc.displayMETActualCases();
                    actualVolume    += salesLineLoc.displayMETActualUnitVolume()/#Million;
                    actualWeight    += salesLineLoc.displayMETActualWeight();

                    //totalPal = 0;
                        
                    metInventLocationLoc = METInventLocation::findByInventLocationId(
                                                                salesLineLoc.inventDim().InventLocationId);
                    if (volume)
                    {
                        totalPal    += real2int(roundUp((volume/metInventLocationLoc.WHSPalletVolume), 1));
                        estTotalPal += real2int(roundUp((actualVolume/metInventLocationLoc.WHSPalletVolume), 1));
                    }
                }
                select forupdate metOrderExtractScreenTmp where metOrderExtractScreenTmp.SalesId == id;
                metOrderExtractScreenTmp.reread();
                ttsbegin;
                metOrderExtractScreenTmp.Weight             = weight;
                metOrderExtractScreenTmp.Volume             = volume;
                metOrderExtractScreenTmp.Cases              = casesLoc;
                metOrderExtractScreenTmp.BrokenCase         = brokenCase;
                metOrderExtractScreenTmp.ActualBrokenCases  = actBrokenCases;
                metOrderExtractScreenTmp.ActualCases        = actualCases;
                metOrderExtractScreenTmp.ActualVolume       = actualVolume;
                metOrderExtractScreenTmp.ActualWeight       = actualWeight;
                metOrderExtractScreenTmp.update();
                ttscommit;
            }
            this.parmMETOrderExtractScreenTmp(metOrderExtractScreenTmp);
        }
        catch (Exception::Error)
        {
            error("@MET:METBulkUpdateError");
        }

        catch (Exception::UpdateConflict)
        {
            if (appl.ttsLevel() == 0)
            {
                if (xSession::currentRetryCount() >= #RetryNum)
                {
                    throw Exception::UpdateConflictNotRecovered;
                }
                else
                {
                    retry;
                }
            }
            else
            {
                throw Exception::UpdateConflict;
            }
        }
        //CE - CB173_SalesOrderExtract - PS
    }

    /// <summary>
    /// Constructs the order extract screen.
    /// </summary>
    /// <param name="_metOrderExtractScreenTmp">
    /// The <c>METOrderExtractScreenTmp</c> instance.
    /// </param>
    /// <param name="_metOrderExtractScreenParameters">
    /// An instance of <c>METOrderExtractScreenParameters</c> to filter the order extract screen form.
    /// </param>
    /// <returns>METOrderExtractScreenProcessor class instance.</returns>
    public static METOrderExtractScreenProcessor construct(
        METOrderExtractScreenTmp                _metOrderExtractScreenTmp,
        METOrderExtractScreenParameters         _metOrderExtractScreenParameters)
    {
        METOrderExtractScreenProcessor   metOrderExtractScreenProcessor;

        metOrderExtractScreenProcessor = new METOrderExtractScreenProcessor();

        metOrderExtractScreenProcessor.populateOrderExtractScreen(_metOrderExtractScreenTmp, _metOrderExtractScreenParameters);

        return metOrderExtractScreenProcessor;
    }

/// <summary>
/// Initialise parameters.
/// </summary>
protected void initParams()
{
    site                = metOrderExtractScreenParameters.parmSite();
    warehouse           = metOrderExtractScreenParameters.parmWarehouse();
    route               = metOrderExtractScreenParameters.parmRoute();
    shippingDatefrom    = metOrderExtractScreenParameters.parmShippingDateConfirmFrom();
    shippingDateTo      = metOrderExtractScreenParameters.parmShippingDateConfirmTo();
    //category            = metOrderExtractScreenParameters.parmCategory();
    extracted           = metOrderExtractScreenParameters.parmExtracted();
    //CS - CB173_SalesOrderExtract - PS
    osg                 = metOrderExtractScreenParameters.parmOrderSplitGroup();
    salesOrderType      = metOrderExtractScreenParameters.parmOrderType();
    custAcc             = metOrderExtractScreenParameters.parmCustAccount();
    isCred              = metOrderExtractScreenParameters.parmCredManagement();
    //CE - CB173_SalesOrderExtract - PS
}

